class _Parser:
    def __init__(self, tokens: list[Token], source_len: int) -> None:
        self.tokens = tokens
        self.source_len = source_len
        self.pos = 0

    def _current(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _consume(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _match(self, kind: str, value: str | None = None) -> Token | None:
        tok = self._current()
        if tok is not None and tok.kind == kind and (value is None or tok.value == value):
            self.pos += 1
            return tok
        return None

    def _expect(self, kind: str, value: str) -> Token:
        tok = self._current()
        if tok is None:
            raise ParseError(f"expected {value!r}, got end of input", self.source_len)
        if tok.kind != kind or tok.value != value:
            raise ParseError(f"expected {value!r}, got {tok.value!r}", tok.position)
        self.pos += 1
        return tok

    def parse(self) -> object:
        if not self.tokens:
            raise ParseError("empty expression", self.source_len)
        node = self._parse_expr()
        extra = self._current()
        if extra is not None:
            raise ParseError(f"unexpected token: {extra.value!r}", extra.position)
        return node

    def _parse_expr(self) -> object:
        return self._parse_or()

    def _parse_or(self) -> object:
        node = self._parse_and()
        while (tok := self._match("KEYWORD", "or")) is not None:
            right = self._parse_and()
            node = BinaryOp("or", node, right, tok.position)
        return node

    def _parse_and(self) -> object:
        node = self._parse_not()
        while (tok := self._match("KEYWORD", "and")) is not None:
            right = self._parse_not()
            node = BinaryOp("and", node, right, tok.position)
        return node

    def _parse_not(self) -> object:
        if (tok := self._match("KEYWORD", "not")) is not None:
            operand = self._parse_not()
            return UnaryOp("not", operand, tok.position)
        return self._parse_comparison()

    def _parse_comparison(self) -> object:
        node = self._parse_additive()
        tok = self._current()
        if tok is not None and tok.kind == "OP" and tok.value in COMPARISON_OPS:
            self._consume()
            right = self._parse_additive()
            node = BinaryOp(str(tok.value), node, right, tok.position)
            next_tok = self._current()
            if next_tok is not None and next_tok.kind == "OP" and next_tok.value in COMPARISON_OPS:
                raise ParseError("comparison operators are non-associative", next_tok.position)
        return node

    def _parse_additive(self) -> object:
        node = self._parse_multiplicative()
        while True:
            tok = self._current()
            if tok is not None and tok.kind == "OP" and tok.value in ADDITIVE_OPS:
                self._consume()
                right = self._parse_multiplicative()
                node = BinaryOp(str(tok.value), node, right, tok.position)
            else:
                break
        return node

    def _parse_multiplicative(self) -> object:
        node = self._parse_unary()
        while True:
            tok = self._current()
            if tok is not None and tok.kind == "OP" and tok.value in MULTIPLICATIVE_OPS:
                self._consume()
                right = self._parse_unary()
                node = BinaryOp(str(tok.value), node, right, tok.position)
            else:
                break
        return node

    def _parse_unary(self) -> object:
        if (tok := self._match("OP", "-")) is not None:
            operand = self._parse_unary()
            return UnaryOp("-", operand, tok.position)
        return self._parse_power()

    def _parse_power(self) -> object:
        node = self._parse_primary()
        if (tok := self._match("OP", "^")) is not None:
            right = self._parse_unary()
            node = BinaryOp("^", node, right, tok.position)
        return node

    def _parse_primary(self) -> object:
        tok = self._current()
        if tok is None:
            raise ParseError("unexpected end of input", self.source_len)

        if tok.kind == "NUMBER":
            self._consume()
            return NumberLiteral(float(tok.value), tok.position)

        if tok.kind == "STRING":
            self._consume()
            return StringLiteral(str(tok.value), tok.position)

        if tok.kind == "KEYWORD" and tok.value in ("true", "false"):
            self._consume()
            return BoolLiteral(tok.value == "true", tok.position)

        if tok.kind == "IDENT":
            self._consume()
            name = str(tok.value)
            if self._match("OP", "(") is not None:
                args: list[object] = []
                if self._match("OP", ")") is None:
                    args.append(self._parse_expr())
                    while self._match("OP", ",") is not None:
                        args.append(self._parse_expr())
                    self._expect("OP", ")")
                return Call(name, args, tok.position)
            return Identifier(name, tok.position)

        if tok.kind == "OP" and tok.value == "(":
            self._consume()
            expr = self._parse_expr()
            self._expect("OP", ")")
            return expr

        raise ParseError(f"unexpected token: {tok.value!r}", tok.position)


def parse(source: str) -> object:
    tokens = tokenize(source)
    return _Parser(tokens, len(source)).parse()

import math
import re
from typing import Callable
from .errors import EvalError

_NUM_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?$")


def format_number(val: float) -> str:
    if val.is_integer():
        return str(int(val))
    return repr(val)


def format_repl_value(val: object) -> str:
    if type(val) is bool:
        return "true" if val else "false"
    if type(val) is float:
        return format_number(val)
    if type(val) is str:
        escaped = (
            val.replace("\\", "\\\\")
            .replace('"', '\\"')
            .replace("\n", "\\n")
            .replace("\r", "\\r")
            .replace("\t", "\\t")
        )
        return f'"{escaped}"'
    raise EvalError(f"unsupported value: {val!r}")


def _check_arity(name: str, expected: int, got: int) -> None:
    if got != expected:
        raise EvalError(f"{name}() takes {expected} argument(s), got {got}")


def _require_number(name: str, val: object) -> float:
    if type(val) is not float:
        raise EvalError(f"{name}() requires number argument(s)")
    return val


def _require_string(name: str, val: object) -> str:
    if type(val) is not str:
        raise EvalError(f"{name}() requires a string argument")
    return val


def _builtin_abs(args: list[object]) -> float:
    x = _require_number("abs", args[0])
    return float(abs(x))


def _builtin_min(args: list[object]) -> float:
    nums = [_require_number("min", a) for a in args]
    return float(min(nums))


def _builtin_max(args: list[object]) -> float:
    nums = [_require_number("max", a) for a in args]
    return float(max(nums))


def _builtin_round(args: list[object]) -> float:
    x = _require_number("round", args[0])
    if len(args) == 1:
        return float(round(x))
    n = _require_number("round", args[1])
    if not n.is_integer():
        raise EvalError("round() second argument must be a whole number")
    return float(round(x, int(n)))


def _builtin_len(args: list[object]) -> float:
    s = _require_string("len", args[0])
    return float(len(s))


def _builtin_upper(args: list[object]) -> str:
    s = _require_string("upper", args[0])
    return s.upper()


def _builtin_lower(args: list[object]) -> str:
    s = _require_string("lower", args[0])
    return s.lower()


def _builtin_str(args: list[object]) -> str:
    val = args[0]
    if type(val) is str:
        return val
    if type(val) is bool:
        return "true" if val else "false"
    if type(val) is float:
        return format_number(val)
    raise EvalError(f"unsupported value for str(): {val!r}")


def _builtin_num(args: list[object]) -> float:
    s = _require_string("num", args[0]).strip()
    if not _NUM_RE.match(s):
        raise EvalError(f"cannot convert {args[0]!r} to number")
    try:
        val = float(s)
    except ValueError as exc:
        raise EvalError(f"cannot convert {args[0]!r} to number") from exc
    if not math.isfinite(val):
        raise EvalError(f"cannot convert {args[0]!r} to number")
    return val


EAGER_BUILTINS: dict[str, tuple[int | str, Callable[[list[object]], object]]] = {
    "abs": (1, _builtin_abs),
    "min": ("1+", _builtin_min),
    "max": ("1+", _builtin_max),
    "round": ("1-2", _builtin_round),
    "len": (1, _builtin_len),
    "upper": (1, _builtin_upper),
    "lower": (1, _builtin_lower),
    "str": (1, _builtin_str),
    "num": (1, _builtin_num),
}


def call_builtin(
    name: str,
    raw_args: list[object],
    eval_fn: Callable[[object], object],
) -> object:
    got = len(raw_args)

    if name == "if":
        _check_arity("if", 3, got)
        cond = eval_fn(raw_args[0])
        if type(cond) is not bool:
            raise EvalError("if() condition must be a boolean")
        return eval_fn(raw_args[1]) if cond else eval_fn(raw_args[2])

    if name not in EAGER_BUILTINS:
        raise EvalError(f"undefined function: {name}")

    arity_spec, func = EAGER_BUILTINS[name]
    if isinstance(arity_spec, int):
        _check_arity(name, arity_spec, got)
    elif arity_spec == "1+":
        if got < 1:
            raise EvalError(f"{name}() takes at least 1 argument(s), got {got}")
    elif arity_spec == "1-2":
        if got not in (1, 2):
            raise EvalError(f"{name}() takes 1 or 2 argument(s), got {got}")

    evaluated_args = [eval_fn(arg) for arg in raw_args]
    return func(evaluated_args)

import math
from .builtins import call_builtin
from .errors import EvalError
from .parser import (
    BinaryOp,
    BoolLiteral,
    Call,
    Identifier,
    NumberLiteral,
    StringLiteral,
    UnaryOp,
    parse,
)


def _eval_node(node: object, env: dict[str, object]) -> object:
    if isinstance(node, NumberLiteral):
        return node.value

    if isinstance(node, StringLiteral):
        return node.value

    if isinstance(node, BoolLiteral):
        return node.value

    if isinstance(node, Identifier):
        if node.name not in env:
            raise EvalError(f"undefined variable: {node.name}", node.position)
        val = env[node.name]
        if type(val) not in (float, str, bool):
            raise EvalError(f"unsupported value for {node.name}: {val!r}", node.position)
        return val

    if isinstance(node, UnaryOp):
        val = _eval_node(node.operand, env)
        if node.op == "-":
            if type(val) is not float:
                raise EvalError("unary '-' requires a number", node.position)
            return -val
        if node.op == "not":
            if type(val) is not bool:
                raise EvalError("'not' requires a boolean", node.position)
            return not val
        raise EvalError(f"unknown unary operator: {node.op}", node.position)

    if isinstance(node, BinaryOp):
        op = node.op

        if op == "and":
            left = _eval_node(node.left, env)
            if type(left) is not bool:
                raise EvalError("'and' requires boolean operands", node.position)
            if not left:
                return False
            right = _eval_node(node.right, env)
            if type(right) is not bool:
                raise EvalError("'and' requires boolean operands", node.position)
            return right

        if op == "or":
            left = _eval_node(node.left, env)
            if type(left) is not bool:
                raise EvalError("'or' requires boolean operands", node.position)
            if left:
                return True
            right = _eval_node(node.right, env)
            if type(right) is not bool:
                raise EvalError("'or' requires boolean operands", node.position)
            return right

        left = _eval_node(node.left, env)
        right = _eval_node(node.right, env)

        if op == "==":
            return type(left) is type(right) and left == right

        if op == "!=":
            return type(left) is not type(right) or left != right

        if op in ("<", "<=", ">", ">="):
            if not (
                (type(left) is float and type(right) is float)
                or (type(left) is str and type(right) is str)
            ):
                raise EvalError(
                    f"'{op}' requires two numbers or two strings", node.position
                )
            if op == "<":
                return left < right  # type: ignore[operator]
            if op == "<=":
                return left <= right  # type: ignore[operator]
            if op == ">":
                return left > right  # type: ignore[operator]
            return left >= right  # type: ignore[operator]

        if op == "+":
            if type(left) is float and type(right) is float:
                return left + right
            if type(left) is str and type(right) is str:
                return left + right
            raise EvalError("'+' requires two numbers or two strings", node.position)

        if op in ("-", "*", "/", "%", "^"):
            if type(left) is not float or type(right) is not float:
                raise EvalError(f"'{op}' requires number operands", node.position)
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if op == "/":
                if right == 0.0:
                    raise EvalError("division by zero", node.position)
                return left / right
            if op == "%":
                if right == 0.0:
                    raise EvalError("modulo by zero", node.position)
                return left % right
            if op == "^":
                try:
                    res = left ** right
                except (ZeroDivisionError, OverflowError, ValueError) as exc:
                    raise EvalError("invalid exponentiation", node.position) from exc
                if isinstance(res, complex) or not math.isfinite(res):
                    raise EvalError(
                        "exponentiation result is not a real number", node.position
                    )
                return float(res)

        raise EvalError(f"unknown binary operator: {op}", node.position)

    if isinstance(node, Call):
        return call_builtin(node.name, node.args, lambda arg: _eval_node(arg, env))

    raise EvalError(f"unknown AST node: {node!r}")


def evaluate(source: str, env: dict[str, object] | None = None) -> object:
    ast = parse(source)
    env_copy = dict(env) if env is not None else {}
    return _eval_node(ast, env_copy)

import re
import sys
from .builtins import format_repl_value
from .errors import MiniLangError
from .evaluator import evaluate
from .lexer import KEYWORDS

_ASSIGN_RE = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)(.*)$")


def main() -> int:
    env: dict[str, object] = {}

    for raw_line in sys.stdin:
        line = raw_line.rstrip("\r\n")
        stripped = line.strip()

        if not stripped:
            continue

        if stripped == ":quit":
            return 0

        if stripped == ":vars":
            for name in sorted(env):
                print(f"{name} = {format_repl_value(env[name])}")
            continue

        match = _ASSIGN_RE.match(line)
        if match and match.group(1) not in KEYWORDS:
            var_name = match.group(1)
            expr_src = match.group(2)
            try:
                val = evaluate(expr_src, env)
            except MiniLangError as err:
                print(f"error: {err}")
            else:
                env[var_name] = val
            continue

        try:
            val = evaluate(line, env)
        except MiniLangError as err:
            print(f"error: {err}")
        else:
            print(format_repl_value(val))

    return 0


if __name__ == "__main__":
    sys.exit(main())
